class NaturalSnowTest{public static void main(String[]a){int previous=-1;boolean mixed=false,thin=false;for(int h:new int[]{290,325,350,375,400,430,470,510}){int covered=0;for(int z=0;z<128;z++)for(int x=0;x<128;x++){float snow=NaturalSnow.cover(h,.1,1,x,z,71,450,120,.5);if(snow>0)covered++;if(snow>0&&snow<=.375)thin=true;if(snow<0||snow>1||snow*8!=Math.round(snow*8))throw new AssertionError("Invalid layer thickness");if(NaturalSnow.cover(h,2,1,x,z,71,450,120,.5)!=0)throw new AssertionError("Snow sticks to cliff");}if(covered<previous)throw new AssertionError("Coverage not gradual");if(covered>1500&&covered<14000)mixed=true;previous=covered;}if(!mixed||!thin)throw new AssertionError("Missing thin scattered transition");System.out.println("PASS: snowline fades through bare/thin/thick patches, coverage increases gradually, steep cliffs stay exposed, and thickness maps to vanilla layers");}}
